      expect(nativeSdkAutomaticReportAction(run, submitted)?.stepId).toBe('verify.report');
      expect(nativeSdkAutomaticReportAction(run, { ...submitted, outcomeId: 'wrong' })).toBeNull();
      run = await runtime.execute({
        runId: run.runId,
