        decision: { choice: 'approved' },
      });
      for (const original of ready.actions.filter((action) => action.stepId === 'verify.checks'))
        expect(run.actions.find((action) => action.id === original.id)).toEqual(original);
      vi.unstubAllEnvs();
    },
  )

