      executorId: 'comet-native-checks',
      context,
    });
    expect(checked.actions.at(-1)).toMatchObject({ stepId: 'verify.verifier', status: 'pending' });
    expect(
      (checked.outputs['verify.requested-checks'].value as { checks: { status: string }[] })
        .checks[0].status,
    ).toBe('passed');
  })

